using namespace std;

int main() {
    int k, c, a;

    while (scanf("%d", &k), k) {
        a = 0;
        int totalInputs = k * (k - 1) / 2;
        int* inputs = new int[totalInputs]; // dynamically allocate array to store inputs
        scanf("%d", &inputs[0]); // read the first input outside the loop
        for (int i = 1; i < totalInputs; i++) {
            scanf("%d", &inputs[i]); // read remaining inputs
        }
        for (int i = 0; i < totalInputs; i++) {
            a += inputs[i]; // sum inputs
        }
        delete[] inputs; // free allocated memory
        printf("%d\n", a / (k - 1));
    }
}

